const raw = $input.first().json.body || $input.first().json;
const stream = String(raw.stream || 'socaas').toLowerCase();

const mapping = {
  socaas: { scope: 'department', key: 'socaas', label: 'n8n-24x7-socaas' },
  vuln: { scope: 'it', key: 'devsecops', label: 'n8n-vuln-scanner' },
  iam_pam: { scope: 'it', key: 'compliance_analysts', label: 'n8n-iam-pam' },
  network: { scope: 'it', key: 'networking', label: 'n8n-network-watch' },
  assets_config: { scope: 'it', key: 'devops', label: 'n8n-assets-config' },
  cab: { scope: 'it', key: 'change_mgmt', label: 'n8n-cab-rfc' }
};

const target = mapping[stream] || mapping.socaas;

return [{
  json: {
    tenantId: raw.tenantId || 'eds-360',
    scope: target.scope,
    key: target.key,
    sourceLabel: raw.sourceLabel || target.label,
    kpis: Array.isArray(raw.kpis) ? raw.kpis : [
      { label: 'Stream Status', value: raw.status || 'Nominal', sub: `Source: ${stream}`, accent: 'text-emerald-300' },
      { label: 'Open Findings', value: String(raw.openCount ?? 0), sub: 'Auto-triaged by n8n', accent: 'text-cyan-300' },
      { label: 'Control Mapping', value: raw.controls || 'SI.L2 / AU.L2', sub: 'CMMC / NIST 800-171', accent: 'text-indigo-300' },
      { label: 'Watch Window', value: '24/7/365', sub: new Date().toISOString().slice(11, 19) + 'Z', accent: 'text-emerald-300' }
    ],
    items: Array.isArray(raw.items) && raw.items.length > 0 ? raw.items : [
      {
        ref: raw.ref || `EVT-${Date.now().toString().slice(-5)}`,
        owner: raw.owner || target.label,
        detail: raw.detail || `${stream.toUpperCase()} telemetry event ingested (${raw.controls || 'SI.L2-3.14.1'})`,
        status: raw.itemStatus || 'compliant'
      }
    ]
  }
}];
